actions.script:
import groovy.json.JsonOutput

// Finds a file uploaded through LibreChat (fileStrategy: local) by its original
// filename. LibreChat prefixes stored files with "<fileId>__", and nests them under
// a per-user directory, so an exact top-level match never works - always search
// recursively and match on either the exact name or the "__<name>" suffix. Picks the
// most recently modified match if the same filename was uploaded more than once.
Closure<File> findUploadedFile = { File root, String targetName ->
    File found = null
    long foundModified = -1L
    if (root.exists()) {
        root.eachFileRecurse { File f ->
            if (f.isFile() && (f.name == targetName || f.name.endsWith('__' + targetName))) {
                if (f.lastModified() > foundModified) { found = f; foundModified = f.lastModified() }
            }
        }
    }
    return found
}

def runValue = ec.entity.makeValue('moqui.math.MathModelRun')
        .setAll([mathModelId: 'MM_PRODUCT_CONTENT_ATTACH',
                 startTime: ec.user.nowTimestamp,
                 parameters: JsonOutput.toJson([productId: productId, sourceFilePath: sourceFilePath,
                         productContentTypeEnumId: productContentTypeEnumId]),
                 hasError: 'N'])
runValue.setSequencedIdPrimary()
runValue.create()
mathModelRunId = runValue.mathModelRunId

try {
    File sourceFile = new File(sourceFilePath as String)
    String filename = sourceFile.getName()
    if (!sourceFile.exists()) {
        String uploadsRoot = ec.user.getPreference('cyber.librechat.uploads.root')
        File resolved = uploadsRoot ? findUploadedFile(new File(uploadsRoot as String), filename) : null
        if (resolved == null) throw new IllegalArgumentException("Could not find '${filename}' as a real path or under the configured LibreChat uploads directory (cyber.librechat.uploads.root=${uploadsRoot}). Pass the plain attachment filename, not a guessed path.")
        sourceFile = resolved
    }

    Map createResult = ec.service.sync().name('create#mantle.product.ProductContent')
            .parameters([productId: productId, productContentTypeEnumId: productContentTypeEnumId,
                    description: description]).call()
    productContentId = createResult.productContentId

    String contentRoot = ec.user.getPreference('mantle.content.large.root') ?: 'dbresource://mantle/content'
    contentLocation = "${contentRoot}/product/${productId}/content_${productContentId}/${filename}"
    def docRr = ec.resource.getLocationReference(contentLocation as String)
    def fileStream = sourceFile.newInputStream()
    try { docRr.putStream(fileStream) } finally { fileStream.close() }

    ec.service.sync().name('update#mantle.product.ProductContent')
            .parameters([productContentId: productContentId, contentLocation: contentLocation]).call()

    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(
                    [productContentId: productContentId, contentLocation: contentLocation])])
            .update()
} catch (Throwable t) {
    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()])
            .update()
    throw t
}

import groovy.json.JsonOutput

// See attach#ProductContentFromPath for why this is needed: LibreChat prefixes
// stored files with "<fileId>__" and nests them per-user, and some model providers
// report their own sandbox path instead of anything Moqui can read directly.
Closure<File> findUploadedFile = { File root, String targetName ->
    File found = null
    long foundModified = -1L
    if (root.exists()) {
        root.eachFileRecurse { File f ->
            if (f.isFile() && (f.name == targetName || f.name.endsWith('__' + targetName))) {
                if (f.lastModified() > foundModified) { found = f; foundModified = f.lastModified() }
            }
        }
    }
    return found
}

def runValue = ec.entity.makeValue('moqui.math.MathModelRun')
        .setAll([mathModelId: 'MM_PRODUCT_FAMILY_CONTENT_ATTACH',
                 startTime: ec.user.nowTimestamp,
                 parameters: JsonOutput.toJson([sourceFilePath: sourceFilePath,
                         categoryContentTypeEnumId: categoryContentTypeEnumId,
                         productCategoryId: productCategoryId, newCategoryName: newCategoryName,
                         productIds: productIds]),
                 hasError: 'N'])
runValue.setSequencedIdPrimary()
runValue.create()
mathModelRunId = runValue.mathModelRunId

try {
    File sourceFile = new File(sourceFilePath as String)
    String filename = sourceFile.getName()
    if (!sourceFile.exists()) {
        String uploadsRoot = ec.user.getPreference('cyber.librechat.uploads.root')
        File resolved = uploadsRoot ? findUploadedFile(new File(uploadsRoot as String), filename) : null
        if (resolved == null) throw new IllegalArgumentException("Could not find '${filename}' as a real path or under the configured LibreChat uploads directory (cyber.librechat.uploads.root=${uploadsRoot}). Pass the plain attachment filename, not a guessed path.")
        sourceFile = resolved
    }

    String effectiveCategoryId = productCategoryId as String
    if (!effectiveCategoryId) {
        if (!newCategoryName) throw new IllegalArgumentException("Either productCategoryId or newCategoryName is required.")
        def existingCategory = ec.entity.find('mantle.product.category.ProductCategory')
                .condition('categoryName', newCategoryName).one()
        if (existingCategory) {
            effectiveCategoryId = existingCategory.productCategoryId as String
        } else {
            Map categoryResult = ec.service.sync().name('create#mantle.product.category.ProductCategory')
                    .parameters([categoryName: newCategoryName, description: newCategoryDescription]).call()
            effectiveCategoryId = categoryResult.productCategoryId as String
        }
    }
    productCategoryId = effectiveCategoryId

    int membersEnsuredCount = 0
    (productIds as List).each { pid ->
        def existingMember = ec.entity.find('mantle.product.category.ProductCategoryMember')
                .condition('productCategoryId', effectiveCategoryId).condition('productId', pid).one()
        if (!existingMember) {
            ec.service.sync().name('create#mantle.product.category.ProductCategoryMember')
                    .parameters([productCategoryId: effectiveCategoryId, productId: pid,
                            fromDate: ec.user.nowTimestamp]).call()
            membersEnsuredCount++
        }
    }
    membersEnsured = membersEnsuredCount

    Map contentResult = ec.service.sync().name('create#mantle.product.category.ProductCategoryContent')
            .parameters([productCategoryId: effectiveCategoryId, categoryContentTypeEnumId: categoryContentTypeEnumId,
                    description: description]).call()
    productCategoryContentId = contentResult.productCategoryContentId

    String contentRoot = ec.user.getPreference('mantle.content.large.root') ?: 'dbresource://mantle/content'
    contentLocation = "${contentRoot}/productCategory/${effectiveCategoryId}/content_${productCategoryContentId}/${filename}"
    def docRr = ec.resource.getLocationReference(contentLocation as String)
    def fileStream = sourceFile.newInputStream()
    try { docRr.putStream(fileStream) } finally { fileStream.close() }

    ec.service.sync().name('update#mantle.product.category.ProductCategoryContent')
            .parameters([productCategoryContentId: productCategoryContentId, contentLocation: contentLocation]).call()

    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(
                    [productCategoryId: effectiveCategoryId, productCategoryContentId: productCategoryContentId,
                     contentLocation: contentLocation, membersEnsured: membersEnsuredCount])])
            .update()
} catch (Throwable t) {
    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()])
            .update()
    throw t
}
